WITH enriched_sales AS (SELECT cs.cs_order_number, cs.cs_bill_customer_sk, cs.cs_ship_mode_sk, cs.cs_item_sk, cs.cs_ext_sales_price, cs.cs_ext_discount_amt, cs.cs_ext_ship_cost, cs.cs_net_profit, cs.cs_sold_date_sk, i.i_brand, i.i_category, sm.sm_type, cs.cs_quantity, ca.ca_city AS bill_city FROM catalog_sales cs JOIN item i ON cs.cs_item_sk = i.i_item_sk JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk JOIN customer_address ca ON cs.cs_bill_addr_sk = ca.ca_address_sk) SELECT e.cs_order_number, e.cs_bill_customer_sk, e.bill_city, e.i_brand, e.i_category, e.sm_type, e.cs_quantity, e.cs_ext_sales_price, e.cs_ext_discount_amt, e.cs_ext_ship_cost, ROUND(e.cs_ext_discount_amt / NULLIF(e.cs_ext_sales_price, 0) * 100, 2) AS discount_percent, ROUND(e.cs_ext_discount_amt / NULLIF(AVG(e.cs_ext_discount_amt) OVER (PARTITION BY e.cs_ship_mode_sk), 0) * 100, 2) AS discount_vs_mode_percent, CASE WHEN e.cs_ext_discount_amt > AVG(e.cs_ext_discount_amt) OVER (PARTITION BY e.cs_ship_mode_sk) * 1.5 THEN 'High Discount' ELSE 'Normal Discount' END AS discount_flag, LAG(e.cs_ext_discount_amt) OVER (PARTITION BY e.cs_bill_customer_sk ORDER BY e.cs_sold_date_sk, e.cs_order_number) AS prev_discount_amt, CASE WHEN e.cs_ext_discount_amt > LAG(e.cs_ext_discount_amt) OVER (PARTITION BY e.cs_bill_customer_sk ORDER BY e.cs_sold_date_sk, e.cs_order_number) THEN 'Increasing' WHEN e.cs_ext_discount_amt < LAG(e.cs_ext_discount_amt) OVER (PARTITION BY e.cs_bill_customer_sk ORDER BY e.cs_sold_date_sk, e.cs_order_number) THEN 'Decreasing' ELSE 'Stable' END AS discount_trend, SUM(e.cs_net_profit) OVER (PARTITION BY e.i_brand ORDER BY e.cs_sold_date_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_brand_profit FROM enriched_sales e WHERE e.cs_ext_sales_price > 0 ORDER BY e.cs_bill_customer_sk, e.cs_sold_date_sk LIMIT 100
